import pathlib,json,copy,yaml,subprocess,tempfile,shutil
class Strict(yaml.SafeLoader):pass
def mapping(loader,node,deep=False):
 loader.flatten_mapping(node);d={}
 for k,v in node.value:
  key=loader.construct_object(k,deep=deep)
  if key in d:raise ValueError('duplicate key')
  d[key]=loader.construct_object(v,deep=deep)
 return d
Strict.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,mapping)
def load(name):return yaml.load(pathlib.Path(name).read_text(encoding='utf-8'),Loader=Strict)

EXPECTED={'groups': [{'name': 'summary-aggregation-boundary', 'interval': '1m', 'rules': [{'record': 'service:summary_latency_seconds:mean', 'expr': '(sum by(service) ((rate(request_seconds_sum[5m]) and on(service,instance) rate(request_seconds_count[5m]))) / sum by(service) ((rate(request_seconds_count[5m]) and on(service,instance) rate(request_seconds_sum[5m])))) and on(service) (sum by(service) ((rate(request_seconds_count[5m]) and on(service,instance) rate(request_seconds_sum[5m]))) > 0)'}, {'record': 'instance:summary_latency_seconds:p99', 'expr': 'request_seconds{quantile="0.99"} and on(service,instance) ((rate(request_seconds_count[5m]) and on(service,instance) rate(request_seconds_sum[5m])) > 0)'}, {'record': 'service:summary_latency_seconds:worst_reported_p99', 'expr': 'max by(service) (instance:summary_latency_seconds:p99)'}]}]}
FIXTURE={'rule_files': ['rules.yaml'], 'evaluation_interval': '1m', 'fuzzy_compare': True, 'tests': [{'interval': '1m', 'input_series': [{'series': 'request_seconds_sum{instance="busy",service="shop"}', 'values': '0+6x7'}, {'series': 'request_seconds_count{instance="busy",service="shop"}', 'values': '0+60x7'}, {'series': 'request_seconds{instance="busy",quantile="0.99",service="shop"}', 'values': '0.5+0x7'}, {'series': 'request_seconds{instance="busy",quantile="0.5",service="shop"}', 'values': '0.01+0x7'}, {'series': 'request_seconds_sum{instance="slow",service="shop"}', 'values': '0+12x7'}, {'series': 'request_seconds_count{instance="slow",service="shop"}', 'values': '0+6x7'}, {'series': 'request_seconds{instance="slow",quantile="0.99",service="shop"}', 'values': '4+0x7'}, {'series': 'request_seconds{instance="slow",quantile="0.5",service="shop"}', 'values': '0.01+0x7'}, {'series': 'request_seconds_sum{instance="a",service="steady"}', 'values': '0+12x7'}, {'series': 'request_seconds_count{instance="a",service="steady"}', 'values': '0+60x7'}, {'series': 'request_seconds{instance="a",quantile="0.99",service="steady"}', 'values': '0.4+0x7'}, {'series': 'request_seconds{instance="a",quantile="0.5",service="steady"}', 'values': '0.01+0x7'}, {'series': 'request_seconds_sum{instance="a",service="idle"}', 'values': '0+0x7'}, {'series': 'request_seconds_count{instance="a",service="idle"}', 'values': '0+0x7'}, {'series': 'request_seconds{instance="a",quantile="0.99",service="idle"}', 'values': '0.3+0x7'}, {'series': 'request_seconds{instance="a",quantile="0.5",service="idle"}', 'values': '0.01+0x7'}, {'series': 'request_seconds_sum{instance="sum-only",service="shop"}', 'values': '0+600x7'}, {'series': 'request_seconds_count{instance="count-only",service="shop"}', 'values': '0+600x7'}], 'promql_expr_test': [{'expr': 'service:summary_latency_seconds:mean', 'eval_time': '5m', 'exp_samples': [{'labels': 'service:summary_latency_seconds:mean{service="shop"}', 'value': 0.2727272727272727}, {'labels': 'service:summary_latency_seconds:mean{service="steady"}', 'value': 0.2}]}, {'expr': 'instance:summary_latency_seconds:p99', 'eval_time': '5m', 'exp_samples': [{'labels': 'instance:summary_latency_seconds:p99{instance="busy",quantile="0.99",service="shop"}', 'value': 0.5}, {'labels': 'instance:summary_latency_seconds:p99{instance="slow",quantile="0.99",service="shop"}', 'value': 4}, {'labels': 'instance:summary_latency_seconds:p99{instance="a",quantile="0.99",service="steady"}', 'value': 0.4}]}, {'expr': 'service:summary_latency_seconds:worst_reported_p99', 'eval_time': '5m', 'exp_samples': [{'labels': 'service:summary_latency_seconds:worst_reported_p99{service="shop"}', 'value': 4}, {'labels': 'service:summary_latency_seconds:worst_reported_p99{service="steady"}', 'value': 0.4}]}, {'expr': 'service:summary_latency_seconds:mean', 'eval_time': '7m', 'exp_samples': [{'labels': 'service:summary_latency_seconds:mean{service="shop"}', 'value': 0.2727272727272727}, {'labels': 'service:summary_latency_seconds:mean{service="steady"}', 'value': 0.2}]}, {'expr': 'instance:summary_latency_seconds:p99', 'eval_time': '7m', 'exp_samples': [{'labels': 'instance:summary_latency_seconds:p99{instance="busy",quantile="0.99",service="shop"}', 'value': 0.5}, {'labels': 'instance:summary_latency_seconds:p99{instance="slow",quantile="0.99",service="shop"}', 'value': 4}, {'labels': 'instance:summary_latency_seconds:p99{instance="a",quantile="0.99",service="steady"}', 'value': 0.4}]}, {'expr': 'service:summary_latency_seconds:worst_reported_p99', 'eval_time': '7m', 'exp_samples': [{'labels': 'service:summary_latency_seconds:worst_reported_p99{service="shop"}', 'value': 4}, {'labels': 'service:summary_latency_seconds:worst_reported_p99{service="steady"}', 'value': 0.4}]}]}]}
r=load('rules.yaml')
assert set(r)=={'groups'} and len(r['groups'])==1
g=r['groups'][0];assert set(g)=={'name','interval','rules'} and g['name']==EXPECTED['groups'][0]['name'] and g['interval']=='1m'
assert len(g['rules'])==len(EXPECTED['groups'][0]['rules'])
for actual,expected in zip(g['rules'],EXPECTED['groups'][0]['rules']):
 assert set(actual)==set(expected)
 assert {k:v for k,v in actual.items() if k!='expr'}=={k:v for k,v in expected.items() if k!='expr'}
 assert isinstance(actual['expr'],str) and actual['expr'].strip()

assert shutil.which('promtool'),'platform must supply native promtool'
